insert into public.recipes
  (id, brewing_method_id, coffee_amount, water_amount, water_temp, vendor_id, last_modified, brew_time)
values
  ('1101', 'cupping', 12, 200, 95, 'timercoffee', now(), 945)
insert into public.recipe_localization
  (id, recipe_id, locale, name, grind_size, short_description)
values
  ('1101-en', '1101', 'en', 'James Hoffmann Home Cupping recipe', 'Medium-fine', 'Cupping is how the coffee industry tastes coffee, and it''s the best way to get to know your own palate. It''s the brewing method with the least human interaction: no pouring technique, no filter, nothing between you and the coffee. James Hoffmann, winner of the World Barista Championship, YouTuber, coffee consultant, and author, adapted it for home use at a gentler 60g/L. Brew a bowl, taste it all the way from hot to room temperature, and pay attention to what changes. Set up a second bowl alongside it whenever you want to compare two coffees side by side. [Watch the tutorial](https://www.youtube.com/watch?v=cSEgP4VNynQ).'),
  ('1101-ar', '1101', 'ar', 'وصفة جيمس هوفمان لتذوق القهوة في المنزل', 'متوسطة النعومة', 'تذوق القهوة (Cupping) هو الأسلوب الذي تتذوق به صناعة القهوة، وأفضل وسيلة لتتعرف على حاسة التذوق لديك. إنها طريقة التحضير الأقل تدخلًا من الإنسان: لا تقنية سكب، ولا فلتر، ولا شيء يفصل بينك وبين القهوة. جيمس هوفمان، الفائز ببطولة العالم للباريستا، يوتيوبر، مستشار القهوة ومؤلف، طوّرها للاستخدام المنزلي بنسبة ألطف تبلغ 60 غ لكل لتر. حضّر وعاءً واحدًا، وتذوقه من السخونة حتى حرارة الغرفة، وانتبه لما يتغير. حضّر وعاءً ثانيًا بجانبه متى أردت مقارنة قهوتين جنبًا إلى جنب. [شاهد الدليل](https://www.youtube.com/watch?v=cSEgP4VNynQ).'),
  ('1101-de', '1101', 'de', 'James Hoffmanns Cupping-Rezept für zu Hause', 'Mittelfein', 'Cupping ist die Art, wie die Kaffeebranche Kaffee verkostet, und der beste Weg, deinen eigenen Geschmackssinn kennenzulernen. Es ist die Zubereitungsmethode mit dem geringsten menschlichen Einfluss: keine Gießtechnik, kein Filter, nichts zwischen dir und dem Kaffee. James Hoffmann, Gewinner der Barista-Weltmeisterschaft, YouTuber, Kaffeeberater und Autor, hat sie mit sanfteren 60 g/l für zu Hause angepasst. Brühe eine Schale, verkoste sie von heiß bis auf Raumtemperatur und achte darauf, was sich verändert. Stell eine zweite Schale daneben, wenn du zwei Kaffees direkt vergleichen willst. [Tutorial ansehen](https://www.youtube.com/watch?v=cSEgP4VNynQ).'),
  ('1101-el', '1101', 'el', 'Συνταγή cupping στο σπίτι του James Hoffmann', 'Μέτριο-λεπτό', 'Το cupping είναι ο τρόπος με τον οποίο η βιομηχανία καφέ δοκιμάζει τον καφέ, και ο καλύτερος τρόπος να γνωρίσετε τη δική σας γεύση. Είναι η μέθοδος παρασκευής με τη μικρότερη ανθρώπινη παρέμβαση: καμία τεχνική έγχυσης, κανένα φίλτρο, τίποτα ανάμεσα σε εσάς και τον καφέ. Ο James Hoffmann, νικητής του World Barista Championship, YouTuber, σύμβουλος καφέ και συγγραφέας, την προσάρμοσε για το σπίτι με μια πιο ήπια αναλογία 60 g/L. Φτιάξτε ένα μπολ, δοκιμάστε το από ζεστό μέχρι τη θερμοκρασία δωματίου και προσέξτε τι αλλάζει. Ετοιμάστε ένα δεύτερο μπολ δίπλα του όποτε θέλετε να συγκρίνετε δύο καφέδες. [Δείτε τον οδηγό](https://www.youtube.com/watch?v=cSEgP4VNynQ).'),
  ('1101-es', '1101', 'es', 'Receta de cupping en casa de James Hoffmann', 'Medio-fino', 'El cupping es la forma en que la industria del café cata el café, y la mejor manera de conocer tu propio paladar. Es el método de preparación con menos intervención humana: sin técnica de vertido, sin filtro, nada entre tú y el café. James Hoffmann, campeón mundial de baristas, creador de contenido, consultor de café y autor, lo adaptó para casa con una proporción más suave de 60 g/L. Prepara un bol, cátalo desde caliente hasta temperatura ambiente y fíjate en lo que cambia. Prepara un segundo bol al lado cuando quieras comparar dos cafés. [Mira el vídeo](https://www.youtube.com/watch?v=cSEgP4VNynQ).'),
  ('1101-fa', '1101', 'fa', 'دستور کاپینگ خانگی جیمز هافمن', 'متوسط‌ریز', 'کاپینگ روشی است که صنعت قهوه با آن قهوه را می‌چشد و بهترین راه برای شناخت ذائقه‌ی خودتان است. کم‌دخالت‌ترین روش دم‌آوری است: نه تکنیک ریختن آب، نه فیلتر، هیچ چیز میان شما و قهوه. جیمز هافمن، قهرمان مسابقات جهانی باریستا، یوتیوبر، مشاور قهوه و نویسنده، آن را با نسبت ملایم‌تر ۶۰ گرم در لیتر برای خانه تنظیم کرده است. یک کاسه دم کنید، آن را از داغ تا دمای اتاق بچشید و به تغییرها دقت کنید. هر وقت خواستید دو قهوه را کنار هم مقایسه کنید، کاسه‌ی دومی هم کنارش دم کنید. [آموزش ویدیویی را ببینید](https://www.youtube.com/watch?v=cSEgP4VNynQ).'),
  ('1101-fi', '1101', 'fi', 'James Hoffmannin kotikuppausresepti', 'Keskihieno', 'Kuppaus on tapa, jolla kahviala maistelee kahvia, ja paras keino oppia tuntemaan oma makuaistisi. Se on valmistustapa, jossa on vähiten ihmisen vaikutusta: ei kaatotekniikkaa, ei suodatinta, ei mitään sinun ja kahvin välissä. James Hoffmann, World Barista Championshipin voittaja, YouTube-sisällöntuottaja, kahvikonsultti ja kirjailija, muokkasi sen kotikäyttöön lempeämmällä 60 g/l suhteella. Valmista yksi kulhollinen, maista sitä kuumasta huoneenlämpöiseen ja kiinnitä huomiota siihen, mikä muuttuu. Valmista viereen toinen kulhollinen aina kun haluat verrata kahta kahvia rinnakkain. [Katso ohjevideo](https://www.youtube.com/watch?v=cSEgP4VNynQ).'),
  ('1101-fr', '1101', 'fr', 'Recette de cupping à la maison de James Hoffmann', 'Moyenne-fine', 'Le cupping est la façon dont l''industrie du café déguste le café, et le meilleur moyen d''apprendre à connaître votre propre palais. C''est la méthode d''infusion avec le moins d''intervention humaine : aucune technique de versement, aucun filtre, rien entre vous et le café. James Hoffmann, champion du monde de barista, YouTubeur, consultant en café et auteur, l''a adaptée à la maison avec un ratio plus doux de 60 g/L. Préparez un bol, dégustez-le du chaud jusqu''à la température ambiante et observez ce qui change. Préparez un deuxième bol à côté dès que vous voulez comparer deux cafés. [Voir le tutoriel](https://www.youtube.com/watch?v=cSEgP4VNynQ).'),
  ('1101-hr', '1101', 'hr', 'Recept Jamesa Hoffmanna za cupping kod kuće', 'Srednje fino', 'Cupping je način na koji industrija kave kuša kavu i najbolji način da upoznaš vlastito nepce. To je metoda pripreme s najmanje ljudskog utjecaja: nema tehnike prelijevanja, nema filtera, ništa između tebe i kave. James Hoffmann, pobjednik Svjetskog prvenstva barista, YouTuber, konzultant za kavu i autor, prilagodio ju je za kod kuće s blažim omjerom od 60 g/L. Pripremi jednu zdjelicu, kušaj je od vruće do sobne temperature i obrati pozornost na to što se mijenja. Pripremi drugu zdjelicu uz nju kad god želiš usporediti dvije kave. [Pogledaj video vodič](https://www.youtube.com/watch?v=cSEgP4VNynQ).'),
  ('1101-id', '1101', 'id', 'Resep Cupping di Rumah oleh James Hoffmann', 'Sedang-halus', 'Cupping adalah cara industri kopi mencicipi kopi, dan cara terbaik untuk mengenal selera Anda sendiri. Ini metode seduh dengan campur tangan manusia paling sedikit: tanpa teknik menuang, tanpa filter, tidak ada yang memisahkan Anda dan kopi. James Hoffmann, pemenang World Barista Championship, YouTuber, konsultan kopi, dan penulis, menyesuaikannya untuk di rumah dengan rasio yang lebih ringan, 60 g/L. Seduh satu mangkuk, cicipi dari panas hingga suhu ruang, dan perhatikan apa yang berubah. Siapkan mangkuk kedua di sebelahnya kapan pun Anda ingin membandingkan dua kopi. [Tonton tutorialnya](https://www.youtube.com/watch?v=cSEgP4VNynQ).'),
  ('1101-it', '1101', 'it', 'Ricetta di cupping casalingo di James Hoffmann', 'Medio-fine', 'Il cupping è il modo in cui l''industria del caffè assaggia il caffè, ed è il modo migliore per conoscere il tuo palato. È il metodo di preparazione con il minor intervento umano: nessuna tecnica di versamento, nessun filtro, niente tra te e il caffè. James Hoffmann, vincitore del Campionato mondiale di barista, YouTuber, consulente del caffè e autore, lo ha adattato alla casa con un rapporto più leggero di 60 g/L. Prepara una ciotola, assaggiala dal caldo fino alla temperatura ambiente e presta attenzione a ciò che cambia. Preparane una seconda accanto ogni volta che vuoi confrontare due caffè. [Guarda il tutorial](https://www.youtube.com/watch?v=cSEgP4VNynQ).'),
  ('1101-ja', '1101', 'ja', 'ジェームズ・ホフマンの家庭でのカッピングレシピ', '中細挽き', 'カッピングはコーヒー業界がコーヒーを評価する方法であり、自分の味覚を知るのに最適な方法です。人の手が最も入らない抽出方法で、注ぎのテクニックもフィルターもなく、あなたとコーヒーの間に何もありません。世界バリスタチャンピオンシップ優勝者であり、YouTuber、コーヒーコンサルタント、作家のジェームズ・ホフマンが、より穏やかな60g/Lの比率で家庭向けに調整しました。1杯分を淹れ、熱い状態から室温まで味わい、何が変わるかに注目してください。2種類のコーヒーを飲み比べたいときは、隣にもう1杯用意しましょう。[チュートリアルを見る](https://www.youtube.com/watch?v=cSEgP4VNynQ)'),
  ('1101-ko', '1101', 'ko', 'James Hoffmann 홈 커핑 레시피', '중간보다 고운 분쇄', '커핑은 커피 업계가 커피를 평가하는 방식이자, 자신의 미각을 알아가는 가장 좋은 방법입니다. 사람의 개입이 가장 적은 추출 방식으로, 붓는 기술도 필터도 없이 당신과 커피 사이에 아무것도 없습니다. World Barista Championship 우승자이자 유튜버, 커피 컨설턴트, 저자인 James Hoffmann이 60g/L의 더 부드러운 비율로 가정용으로 다듬었습니다. 한 잔을 추출해 뜨거울 때부터 실온이 될 때까지 맛보며 무엇이 달라지는지 살펴보세요. 두 가지 커피를 비교하고 싶을 때는 옆에 한 잔을 더 준비하세요. [튜토리얼 보기](https://www.youtube.com/watch?v=cSEgP4VNynQ).'),
  ('1101-nl', '1101', 'nl', 'James Hoffmann cuppingrecept voor thuis', 'Middelfijn', 'Cupping is hoe de koffiebranche koffie proeft, en de beste manier om je eigen smaak te leren kennen. Het is de zetmethode met de minste menselijke invloed: geen schenktechniek, geen filter, niets tussen jou en de koffie. James Hoffmann, winnaar van het World Barista Championship, YouTuber, koffieconsultant en auteur, paste haar aan voor thuis met een mildere verhouding van 60 g/L. Zet één kom, proef hem van heet tot kamertemperatuur en let op wat er verandert. Zet er een tweede kom naast wanneer je twee koffies naast elkaar wilt vergelijken. [Bekijk de instructievideo](https://www.youtube.com/watch?v=cSEgP4VNynQ).'),
  ('1101-no', '1101', 'no', 'James Hoffmanns cuppingoppskrift for hjemmebruk', 'Middels fin', 'Cupping er måten kaffebransjen smaker kaffe på, og den beste måten å bli kjent med din egen smakssans. Det er bryggemetoden med minst menneskelig påvirkning: ingen helleteknikk, ingen filter, ingenting mellom deg og kaffen. James Hoffmann, vinner av World Barista Championship, YouTube-skaper, kaffekonsulent og forfatter, tilpasset den til hjemmebruk med et mildere forhold på 60 g/l. Brygg én skål, smak på den fra varm til romtemperatur, og legg merke til hva som endrer seg. Brygg en skål til ved siden av når du vil sammenligne to kaffer. [Se veiledningen](https://www.youtube.com/watch?v=cSEgP4VNynQ).'),
  ('1101-pl', '1101', 'pl', 'Domowy cupping według Jamesa Hoffmanna', 'Średnio drobno', 'Cupping to sposób, w jaki branża kawowa degustuje kawę, i najlepsza droga do poznania własnego podniebienia. To metoda parzenia z najmniejszym udziałem człowieka: żadnej techniki przelewania, żadnego filtra, nic między tobą a kawą. James Hoffmann, zwycięzca World Barista Championship, twórca internetowy, konsultant kawowy i autor, dostosował ją do domu, stosując łagodniejsze 60 g/l. Zaparz jedną miseczkę, degustuj ją od gorącej aż do temperatury pokojowej i zwracaj uwagę na to, co się zmienia. Postaw obok drugą miseczkę, gdy zechcesz porównać dwie kawy. [Obejrzyj instruktaż](https://www.youtube.com/watch?v=cSEgP4VNynQ).'),
  ('1101-pt', '1101', 'pt', 'Receita de cupping em casa de James Hoffmann', 'Média-fina', 'O cupping é a forma como a indústria do café prova café, e o melhor jeito de conhecer o seu próprio paladar. É o método de preparo com a menor interferência humana: sem técnica de despejo, sem filtro, nada entre você e o café. James Hoffmann, campeão da World Barista Championship, YouTuber, consultor de café e autor, adaptou o método para casa com uma proporção mais suave de 60 g/L. Prepare uma tigela, prove do quente até a temperatura ambiente e preste atenção no que muda. Prepare uma segunda tigela ao lado sempre que quiser comparar dois cafés. [Assista ao tutorial](https://www.youtube.com/watch?v=cSEgP4VNynQ).'),
  ('1101-ro', '1101', 'ro', 'Rețeta de cupping acasă a lui James Hoffmann', 'Medie-fină', 'Cupping-ul este modul în care industria cafelei degustă cafeaua și cea mai bună cale de a-ți cunoaște propriul gust. Este metoda de preparare cu cea mai mică intervenție umană: fără tehnică de turnare, fără filtru, nimic între tine și cafea. James Hoffmann, câștigător al World Barista Championship, YouTuber, consultant în domeniul cafelei și autor, a adaptat-o pentru acasă cu un raport mai blând, de 60 g/L. Prepară un bol, degustă-l de la fierbinte până la temperatura camerei și fii atent la ce se schimbă. Pregătește un al doilea bol alături ori de câte ori vrei să compari două cafele. [Urmărește tutorialul](https://www.youtube.com/watch?v=cSEgP4VNynQ).'),
  ('1101-ru', '1101', 'ru', 'Домашний каппинг от Джеймса Хоффманна', 'Средне-мелкий', 'Каппинг — это способ, которым кофейная индустрия дегустирует кофе, и лучший способ узнать собственный вкус. Это метод заваривания с наименьшим вмешательством человека: никакой техники пролива, никакого фильтра, ничего между вами и кофе. Джеймс Хоффманн, победитель чемпионата мира среди бариста, ютубер, кофейный консультант и писатель, адаптировал его для дома, взяв более мягкие 60 г/л. Заварите одну чашу, пробуйте её от горячей до комнатной температуры и обращайте внимание на то, что меняется. Поставьте рядом вторую чашу, когда захотите сравнить два кофе. [Посмотрите видео](https://www.youtube.com/watch?v=cSEgP4VNynQ).'),
  ('1101-tr', '1101', 'tr', 'James Hoffmann evde cupping tarifi', 'Orta-ince', 'Cupping, kahve sektörünün kahveyi tattığı yöntemdir ve kendi damak zevkinizi tanımanın en iyi yoludur. İnsan müdahalesinin en az olduğu demleme yöntemidir: dökme tekniği yok, filtre yok, sizinle kahve arasında hiçbir şey yok. World Barista Championship şampiyonu, YouTuber, kahve danışmanı ve yazar James Hoffmann, yöntemi 60 g/L gibi daha yumuşak bir oranla ev için uyarladı. Bir kâse demleyin, sıcaktan oda sıcaklığına kadar tadına bakın ve neyin değiştiğine dikkat edin. İki kahveyi yan yana karşılaştırmak istediğinizde yanına ikinci bir kâse demleyin. [Eğitim videosunu izleyin](https://www.youtube.com/watch?v=cSEgP4VNynQ).'),
  ('1101-uk', '1101', 'uk', 'Домашній капінг від Джеймса Гоффманна', 'Середньо-дрібний', 'Капінг — це спосіб, у який кавова індустрія дегустує каву, і найкращий шлях пізнати власний смак. Це метод заварювання з найменшим втручанням людини: жодної техніки проливання, жодного фільтра, нічого між вами та кавою. Джеймс Гоффманн, переможець World Barista Championship, ютубер, консультант з кави та автор, адаптував його для дому з м''якшим співвідношенням 60 г/л. Заваріть одну чашу, куштуйте її від гарячої до кімнатної температури й звертайте увагу на те, що змінюється. Поставте поряд другу чашу, коли захочете порівняти дві кави. [Перегляньте відеоінструкцію](https://www.youtube.com/watch?v=cSEgP4VNynQ).'),
  ('1101-zh', '1101', 'zh', 'James Hoffmann 家庭杯测配方', '中细', '杯测是咖啡行业品鉴咖啡的方式，也是了解自己味觉的最佳途径。它是人为干预最少的冲煮方法：没有注水技巧，没有滤纸，你与咖啡之间没有任何阻隔。世界咖啡师大赛冠军、YouTuber、咖啡顾问及作者 James Hoffmann 将其调整为更温和的 60 g/L，适合在家使用。冲一碗，从滚烫一直喝到室温，留意其中的变化。想要对比两支咖啡时，在旁边再冲一碗即可。[观看教程](https://www.youtube.com/watch?v=cSEgP4VNynQ)。')
insert into public.steps
  (id, recipe_id, step_order, description, "time", locale)
values
  ('1101-1-en', '1101', 1, 'Grind a small handful of beans first to purge the grinder. Then grind <final_coffee_amount>g at the finer end of medium-fine and weigh it straight into the bowl or mug you''ll brew in.', '0', 'en'),
  ('1101-2-en', '1101', 2, 'Place the bowl on the scale and zero it out. Pour <final_water_amount>g of hot water over the grounds — no need to be gentle or precise with the pour.', '15', 'en'),
  ('1101-3-en', '1101', 3, 'Let the coffee steep for 4 minutes. A crust of grounds will form on top.', '240', 'en'),
  ('1101-4-en', '1101', 4, 'Gently stir the crust three times with a spoon, smelling the aroma as it releases. Most of the grounds will sink to the bottom.', '15', 'en'),
  ('1101-5-en', '1101', 5, 'With a second, clean spoon, skim off the foam and any grounds still floating on top.', '15', 'en'),
  ('1101-6-en', '1101', 6, 'Let the coffee cool for at least 10 minutes. Straight after brewing it will burn your tongue, and it''s almost impossible to taste anything that hot.', '600', 'en'),
  ('1101-7-en', '1101', 7, 'Slurp a spoonful, spraying the coffee across your mouth to turn up the volume on its flavours. Keep tasting as it cools to room temperature — it changes a lot on the way down, and gets easier to taste.', '60', 'en'),
  ('1101-1-ar', '1101', 1, 'اطحن حفنة صغيرة من الحبوب أولًا لتنظيف المطحنة. ثم اطحن <final_coffee_amount>غ بدرجة متوسطة النعومة تميل إلى الناعمة، وزِنها مباشرةً في الوعاء أو الكوب الذي ستحضّر فيه.', '0', 'ar'),
  ('1101-2-ar', '1101', 2, 'ضع الوعاء على الميزان واضبطه على الصفر. اسكب <final_water_amount>غ من الماء الساخن فوق القهوة المطحونة — لا حاجة لأن يكون السكب لطيفًا أو دقيقًا.', '15', 'ar'),
  ('1101-3-ar', '1101', 3, 'اترك القهوة تنقع لمدة 4 دقائق. ستتكوّن قشرة من القهوة المطحونة على السطح.', '240', 'ar'),
  ('1101-4-ar', '1101', 4, 'حرّك القشرة برفق ثلاث مرات بملعقة، وتنشّق الرائحة أثناء تصاعدها. سيهبط معظم القهوة المطحونة إلى القاع.', '15', 'ar'),
  ('1101-5-ar', '1101', 5, 'بملعقة ثانية نظيفة، أزل الرغوة وأي قهوة مطحونة ما زالت طافية على السطح.', '15', 'ar'),
  ('1101-6-ar', '1101', 6, 'اترك القهوة تبرد 10 دقائق على الأقل. بعد التحضير مباشرة ستحرق لسانك، ومن المستحيل تقريبًا تذوق أي شيء عند هذه الحرارة.', '600', 'ar'),
  ('1101-7-ar', '1101', 7, 'ارشف ملعقة، ووزّع القهوة في فمك كله لتظهر النكهات بوضوح أكبر. واصل التذوق بينما تبرد حتى حرارة الغرفة — فهي تتغير كثيرًا في طريقها، ويصبح تذوقها أسهل.', '60', 'ar'),
  ('1101-1-de', '1101', 1, 'Mahle zuerst eine kleine Handvoll Bohnen, um die Mühle zu spülen. Mahle dann <final_coffee_amount>g im feineren Bereich von mittelfein und wiege sie direkt in die Schale oder Tasse ein, in der du brühst.', '0', 'de'),
  ('1101-2-de', '1101', 2, 'Stell die Schale auf die Waage und stelle sie auf Null. Gieße <final_water_amount>g heißes Wasser über das Kaffeemehl – du musst dabei weder vorsichtig noch präzise sein.', '15', 'de'),
  ('1101-3-de', '1101', 3, 'Lass den Kaffee 4 Minuten ziehen. Auf der Oberfläche bildet sich eine Kruste aus Kaffeemehl.', '240', 'de'),
  ('1101-4-de', '1101', 4, 'Rühre die Kruste mit einem Löffel dreimal vorsichtig um und rieche dabei das Aroma, das frei wird. Das meiste Kaffeemehl sinkt zu Boden.', '15', 'de'),
  ('1101-5-de', '1101', 5, 'Nimm einen zweiten, sauberen Löffel und schöpfe den Schaum und alles ab, was noch oben schwimmt.', '15', 'de'),
  ('1101-6-de', '1101', 6, 'Lass den Kaffee mindestens 10 Minuten abkühlen. Direkt nach dem Brühen verbrennst du dir die Zunge, und so heiß lässt sich fast nichts schmecken.', '600', 'de'),
  ('1101-7-de', '1101', 7, 'Schlürfe einen Löffel voll und verteile den Kaffee dabei im ganzen Mund, um die Aromen lauter zu machen. Verkoste weiter, während er auf Raumtemperatur abkühlt – er verändert sich dabei stark und wird immer leichter zu schmecken.', '60', 'de'),
  ('1101-1-el', '1101', 1, 'Αλέστε πρώτα μια μικρή χούφτα κόκκους για να καθαρίσετε τον μύλο. Στη συνέχεια αλέστε <final_coffee_amount>g σε μέτριο-λεπτό, προς το πιο λεπτό, και ζυγίστε τον απευθείας μέσα στο μπολ ή την κούπα όπου θα κάνετε την παρασκευή.', '0', 'el'),
  ('1101-2-el', '1101', 2, 'Τοποθετήστε το μπολ στη ζυγαριά και μηδενίστε τη. Ρίξτε <final_water_amount>g ζεστό νερό πάνω στον αλεσμένο καφέ — δεν χρειάζεται να είστε προσεκτικοί ή ακριβείς στο ρίξιμο.', '15', 'el'),
  ('1101-3-el', '1101', 3, 'Αφήστε τον καφέ σε εμβάπτιση για 4 λεπτά. Στην επιφάνεια θα σχηματιστεί μια κρούστα από αλεσμένο καφέ.', '240', 'el'),
  ('1101-4-el', '1101', 4, 'Ανακατέψτε απαλά την κρούστα τρεις φορές με ένα κουτάλι, μυρίζοντας το άρωμα καθώς απελευθερώνεται. Ο περισσότερος αλεσμένος καφές θα κατακαθίσει στον πάτο.', '15', 'el'),
  ('1101-5-el', '1101', 5, 'Με ένα δεύτερο, καθαρό κουτάλι, αφαιρέστε τον αφρό και ό,τι επιπλέει ακόμη στην επιφάνεια.', '15', 'el'),
  ('1101-6-el', '1101', 6, 'Αφήστε τον καφέ να κρυώσει τουλάχιστον 10 λεπτά. Αμέσως μετά την παρασκευή θα σας κάψει τη γλώσσα, και σε τέτοια θερμοκρασία είναι σχεδόν αδύνατο να γευτείτε οτιδήποτε.', '600', 'el'),
  ('1101-7-el', '1101', 7, 'Ρουφήξτε μια κουταλιά, ψεκάζοντας τον καφέ σε όλο το στόμα σας για να δυναμώσετε τις γεύσεις. Συνεχίστε να δοκιμάζετε καθώς κρυώνει μέχρι τη θερμοκρασία δωματίου — αλλάζει πολύ στην πορεία και γίνεται όλο και πιο εύκολο να τον γευτείτε.', '60', 'el'),
  ('1101-1-es', '1101', 1, 'Muele primero un pequeño puñado de granos para purgar el molino. Después muele <final_coffee_amount>g en un medio-fino tirando a fino y pésalo directamente en el bol o la taza donde vayas a preparar.', '0', 'es'),
  ('1101-2-es', '1101', 2, 'Coloca el bol sobre la balanza y ponla a cero. Vierte <final_water_amount>g de agua caliente sobre el café molido: no hace falta que el vertido sea suave ni preciso.', '15', 'es'),
  ('1101-3-es', '1101', 3, 'Deja el café en infusión durante 4 minutos. En la superficie se formará una costra de café molido.', '240', 'es'),
  ('1101-4-es', '1101', 4, 'Remueve la costra suavemente tres veces con una cuchara y huele el aroma que se libera. La mayor parte del café molido se irá al fondo.', '15', 'es'),
  ('1101-5-es', '1101', 5, 'Con una segunda cuchara limpia, retira la espuma y lo que siga flotando en la superficie.', '15', 'es'),
  ('1101-6-es', '1101', 6, 'Deja enfriar el café al menos 10 minutos. Recién preparado te quemará la lengua, y así de caliente es casi imposible saborear nada.', '600', 'es'),
  ('1101-7-es', '1101', 7, 'Sorbe una cucharada pulverizando el café por toda la boca para subir el volumen de sus sabores. Sigue catando mientras se enfría hasta temperatura ambiente: cambia mucho por el camino y cada vez es más fácil de saborear.', '60', 'es'),
  ('1101-1-fa', '1101', 1, 'ابتدا یک مشت کوچک دانه آسیاب کنید تا آسیاب تمیز شود. سپس <final_coffee_amount> گرم را با درجه‌ی متوسط‌ریز، متمایل به ریز، آسیاب کنید و مستقیم داخل کاسه یا لیوانی که در آن دم می‌کنید وزن کنید.', '0', 'fa'),
  ('1101-2-fa', '1101', 2, 'کاسه را روی ترازو بگذارید و آن را صفر کنید. <final_water_amount> گرم آب داغ روی قهوه آسیاب‌شده بریزید — لازم نیست ریختن آب آرام یا دقیق باشد.', '15', 'fa'),
  ('1101-3-fa', '1101', 3, 'بگذارید قهوه ۴ دقیقه خیس بخورد. روی سطح، لایه‌ای از قهوه آسیاب‌شده تشکیل می‌شود.', '240', 'fa'),
  ('1101-4-fa', '1101', 4, 'با یک قاشق، سه بار به‌آرامی لایه‌ی سطح را هم بزنید و همزمان عطری را که آزاد می‌شود ببویید. بیشتر قهوه آسیاب‌شده به ته کاسه می‌نشیند.', '15', 'fa'),
  ('1101-5-fa', '1101', 5, 'با قاشق دوم و تمیز، کف و هر چه هنوز روی سطح شناور است را بردارید.', '15', 'fa'),
  ('1101-6-fa', '1101', 6, 'بگذارید قهوه دست‌کم ۱۰ دقیقه خنک شود. بلافاصله پس از دم‌آوری زبانتان را می‌سوزاند و در آن دما چشیدن تقریباً غیرممکن است.', '600', 'fa'),
  ('1101-7-fa', '1101', 7, 'یک قاشق را هورت بکشید و قهوه را در تمام دهانتان پخش کنید تا طعم‌ها پررنگ‌تر شوند. تا وقتی به دمای اتاق برسد به چشیدن ادامه دهید — در این مسیر بسیار تغییر می‌کند و چشیدنش آسان‌تر می‌شود.', '60', 'fa'),
  ('1101-1-fi', '1101', 1, 'Jauha ensin pieni kourallinen papuja myllyn puhdistamiseksi. Jauha sitten <final_coffee_amount> g keskihienoksi, hienomman pään puolelle, ja punnitse se suoraan siihen kulhoon tai mukiin, jossa haudutat.', '0', 'fi'),
  ('1101-2-fi', '1101', 2, 'Aseta kulho vaa''alle ja nollaa vaaka. Kaada <final_water_amount> g kuumaa vettä kahvijauheen päälle — kaatoa ei tarvitse tehdä varovasti tai tarkasti.', '15', 'fi'),
  ('1101-3-fi', '1101', 3, 'Anna kahvin hautua 4 minuuttia. Pinnalle muodostuu kahvijauheesta kuori.', '240', 'fi'),
  ('1101-4-fi', '1101', 4, 'Sekoita kuorta varovasti kolme kertaa lusikalla ja haistele vapautuvaa tuoksua. Suurin osa kahvijauheesta vajoaa pohjaan.', '15', 'fi'),
  ('1101-5-fi', '1101', 5, 'Poista toisella, puhtaalla lusikalla vaahto ja kaikki pinnalla vielä kelluva.', '15', 'fi'),
  ('1101-6-fi', '1101', 6, 'Anna kahvin jäähtyä vähintään 10 minuuttia. Heti haudutuksen jälkeen se polttaa kielen, eikä niin kuumasta kahvista maista juuri mitään.', '600', 'fi'),
  ('1101-7-fi', '1101', 7, 'Ryystä lusikallinen ja suihkuta kahvi suuhusi, niin maut voimistuvat. Jatka maistelua, kunnes kahvi on jäähtynyt huoneenlämpöiseksi — se muuttuu matkalla paljon ja on koko ajan helpompi maistaa.', '60', 'fi'),
  ('1101-1-fr', '1101', 1, 'Moulez d''abord une petite poignée de grains pour purger le moulin. Moulez ensuite <final_coffee_amount>g dans le bas de la mouture moyenne-fine et pesez-la directement dans le bol ou la tasse dans lequel vous allez infuser.', '0', 'fr'),
  ('1101-2-fr', '1101', 2, 'Placez le bol sur la balance et tarez-la. Versez <final_water_amount>g d''eau chaude sur la mouture — inutile de verser doucement ou avec précision.', '15', 'fr'),
  ('1101-3-fr', '1101', 3, 'Laissez le café infuser 4 minutes. Une croûte de mouture se forme à la surface.', '240', 'fr'),
  ('1101-4-fr', '1101', 4, 'Remuez doucement la croûte trois fois avec une cuillère en sentant les arômes qui se libèrent. La majeure partie de la mouture tombe au fond.', '15', 'fr'),
  ('1101-5-fr', '1101', 5, 'Avec une seconde cuillère propre, retirez la mousse et tout ce qui flotte encore à la surface.', '15', 'fr'),
  ('1101-6-fr', '1101', 6, 'Laissez le café refroidir au moins 10 minutes. Juste après l''infusion, il vous brûlerait la langue et il est presque impossible d''en percevoir quoi que ce soit.', '600', 'fr'),
  ('1101-7-fr', '1101', 7, 'Aspirez une cuillerée en pulvérisant le café dans toute la bouche pour amplifier ses saveurs. Continuez à déguster pendant qu''il refroidit jusqu''à la température ambiante : il change beaucoup en chemin et devient de plus en plus facile à goûter.', '60', 'fr'),
  ('1101-1-hr', '1101', 1, 'Prvo samelji malu šaku zrna da pročistiš mlinac. Zatim samelji <final_coffee_amount> g srednje fino, bliže finom, i izvaži kavu izravno u zdjelicu ili šalicu u kojoj ćeš pripremati.', '0', 'hr'),
  ('1101-2-hr', '1101', 2, 'Stavi zdjelicu na vagu i iznultiraj je. Ulij <final_water_amount> g vruće vode preko mljevene kave — ne moraš ulijevati nježno ni precizno.', '15', 'hr'),
  ('1101-3-hr', '1101', 3, 'Pusti kavu da se namače 4 minute. Na površini će se stvoriti korica od mljevene kave.', '240', 'hr'),
  ('1101-4-hr', '1101', 4, 'Nježno promiješaj koricu tri puta žlicom i pritom pomiriši aromu koja se oslobađa. Većina mljevene kave potonut će na dno.', '15', 'hr'),
  ('1101-5-hr', '1101', 5, 'Drugom, čistom žlicom ukloni pjenu i sve što još pluta na površini.', '15', 'hr'),
  ('1101-6-hr', '1101', 6, 'Pusti kavu da se hladi barem 10 minuta. Odmah nakon pripreme opekla bi ti jezik, a tako vruću kavu gotovo je nemoguće kušati.', '600', 'hr'),
  ('1101-7-hr', '1101', 7, 'Srkni punu žlicu i rasprši kavu po cijelim ustima kako bi pojačao okuse. Nastavi kušati dok se hladi do sobne temperature — mijenja se jako putem i sve ju je lakše kušati.', '60', 'hr'),
  ('1101-1-id', '1101', 1, 'Giling dulu segenggam kecil biji kopi untuk membersihkan sisa di grinder. Lalu giling <final_coffee_amount>g pada tingkat sedang-halus yang condong ke halus dan timbang langsung ke dalam mangkuk atau cangkir yang akan Anda pakai menyeduh.', '0', 'id'),
  ('1101-2-id', '1101', 2, 'Letakkan mangkuk di atas timbangan dan nolkan beratnya. Tuang <final_water_amount>g air panas ke atas bubuk kopi — tidak perlu menuang dengan perlahan atau presisi.', '15', 'id'),
  ('1101-3-id', '1101', 3, 'Biarkan kopi terendam selama 4 menit. Di permukaan akan terbentuk kerak dari bubuk kopi.', '240', 'id'),
  ('1101-4-id', '1101', 4, 'Aduk kerak itu perlahan tiga kali dengan sendok sambil mencium aroma yang keluar. Sebagian besar bubuk kopi akan turun ke dasar.', '15', 'id'),
  ('1101-5-id', '1101', 5, 'Dengan sendok kedua yang bersih, angkat busa dan bubuk yang masih mengapung di permukaan.', '15', 'id'),
  ('1101-6-id', '1101', 6, 'Biarkan kopi mendingin setidaknya 10 menit. Tepat setelah diseduh kopi akan membakar lidah Anda, dan hampir mustahil mencicipi apa pun sepanas itu.', '600', 'id'),
  ('1101-7-id', '1101', 7, 'Seruput satu sendok sambil menyemprotkan kopi ke seluruh mulut agar rasanya terasa lebih jelas. Terus cicipi sampai kopi mencapai suhu ruang — rasanya banyak berubah di sepanjang jalan dan makin mudah dicicipi.', '60', 'id'),
  ('1101-1-it', '1101', 1, 'Macina prima una piccola manciata di chicchi per pulire il macinacaffè. Poi macina <final_coffee_amount>g su un medio-fine tendente al fine e pesalo direttamente nella ciotola o nella tazza in cui preparerai.', '0', 'it'),
  ('1101-2-it', '1101', 2, 'Metti la ciotola sulla bilancia e azzerala. Versa <final_water_amount>g di acqua calda sul caffè macinato: non serve versare con delicatezza né con precisione.', '15', 'it'),
  ('1101-3-it', '1101', 3, 'Lascia il caffè in infusione per 4 minuti. In superficie si formerà una crosta di caffè macinato.', '240', 'it'),
  ('1101-4-it', '1101', 4, 'Mescola delicatamente la crosta tre volte con un cucchiaio, annusando l''aroma che si libera. La maggior parte del caffè macinato scenderà sul fondo.', '15', 'it'),
  ('1101-5-it', '1101', 5, 'Con un secondo cucchiaio pulito, togli la schiuma e tutto ciò che galleggia ancora in superficie.', '15', 'it'),
  ('1101-6-it', '1101', 6, 'Lascia raffreddare il caffè per almeno 10 minuti. Appena preparato ti brucerebbe la lingua e a quella temperatura è quasi impossibile assaggiare qualcosa.', '600', 'it'),
  ('1101-7-it', '1101', 7, 'Sorseggia una cucchiaiata aspirando, così da spruzzare il caffè in tutta la bocca e alzare il volume dei suoi aromi. Continua ad assaggiare mentre si raffredda fino a temperatura ambiente: cambia moltissimo lungo il percorso e diventa sempre più facile da assaggiare.', '60', 'it'),
  ('1101-1-ja', '1101', 1, 'まずグラインダーを掃除するために少量の豆を挽いて捨てます。次に<final_coffee_amount>gを中細挽きのやや細かめに挽き、抽出に使うボウルまたはマグに直接量り入れます。', '0', 'ja'),
  ('1101-2-ja', '1101', 2, 'ボウルをはかりに載せてゼロにします。<final_water_amount>gのお湯を挽いたコーヒーに注ぎます。ていねいに、正確に注ぐ必要はありません。', '15', 'ja'),
  ('1101-3-ja', '1101', 3, 'コーヒーを4分間浸漬させます。表面にコーヒー粉のクラストができます。', '240', 'ja'),
  ('1101-4-ja', '1101', 4, 'スプーンでクラストを3回やさしくかき混ぜ、立ちのぼる香りをかぎます。粉のほとんどは底に沈みます。', '15', 'ja'),
  ('1101-5-ja', '1101', 5, '2本目のきれいなスプーンで、泡と表面に浮いている粉を取り除きます。', '15', 'ja'),
  ('1101-6-ja', '1101', 6, 'コーヒーを10分以上冷まします。淹れた直後は舌をやけどするほど熱く、その温度ではほとんど味がわかりません。', '600', 'ja'),
  ('1101-7-ja', '1101', 7, 'スプーン1杯をすすり、コーヒーを口全体に霧のように広げて風味を強く感じ取ります。室温まで冷める間、味わい続けてください。冷めるにつれて味は大きく変化し、感じ取りやすくなります。', '60', 'ja'),
  ('1101-1-ko', '1101', 1, '먼저 원두 한 줌을 갈아 그라인더를 비워내세요. 그런 다음 <final_coffee_amount>g을 중간보다 고운 분쇄로, 조금 더 곱게 갈아 추출할 볼이나 머그에 바로 계량해 담으세요.', '0', 'ko'),
  ('1101-2-ko', '1101', 2, '볼을 저울에 올리고 영점으로 맞추세요. 분쇄한 커피 위에 <final_water_amount>g의 뜨거운 물을 부으세요. 조심스럽거나 정확하게 부을 필요는 없습니다.', '15', 'ko'),
  ('1101-3-ko', '1101', 3, '커피를 4분 동안 침지하세요. 표면에 분쇄한 커피로 된 크러스트가 생깁니다.', '240', 'ko'),
  ('1101-4-ko', '1101', 4, '스푼으로 크러스트를 세 번 부드럽게 저으면서 퍼지는 향을 맡으세요. 대부분의 커피는 바닥으로 가라앉습니다.', '15', 'ko'),
  ('1101-5-ko', '1101', 5, '두 번째 깨끗한 스푼으로 거품과 표면에 아직 떠 있는 커피를 걷어내세요.', '15', 'ko'),
  ('1101-6-ko', '1101', 6, '커피를 최소 10분 동안 식히세요. 추출 직후에는 혀를 델 정도로 뜨거워서 그 온도에서는 거의 아무 맛도 느낄 수 없습니다.', '600', 'ko'),
  ('1101-7-ko', '1101', 7, '한 스푼을 후루룩 들이마시며 커피를 입안 전체에 뿌리듯 퍼뜨려 향미를 더 크게 느껴 보세요. 실온이 될 때까지 계속 맛보세요. 식어 가는 동안 맛이 크게 달라지고 점점 느끼기 쉬워집니다.', '60', 'ko'),
  ('1101-1-nl', '1101', 1, 'Maal eerst een kleine handvol bonen om de molen door te spoelen. Maal daarna <final_coffee_amount>g middelfijn, aan de fijne kant, en weeg het direct af in de kom of mok waarin je gaat zetten.', '0', 'nl'),
  ('1101-2-nl', '1101', 2, 'Zet de kom op de weegschaal en breng deze op nul. Giet <final_water_amount>g heet water over de gemalen koffie — je hoeft niet voorzichtig of precies te schenken.', '15', 'nl'),
  ('1101-3-nl', '1101', 3, 'Laat de koffie 4 minuten trekken. Op het oppervlak vormt zich een korst van gemalen koffie.', '240', 'nl'),
  ('1101-4-nl', '1101', 4, 'Roer de korst voorzichtig drie keer met een lepel en ruik aan het aroma dat vrijkomt. De meeste koffie zakt naar de bodem.', '15', 'nl'),
  ('1101-5-nl', '1101', 5, 'Schep met een tweede, schone lepel het schuim en alles wat nog drijft van het oppervlak.', '15', 'nl'),
  ('1101-6-nl', '1101', 6, 'Laat de koffie minstens 10 minuten afkoelen. Direct na het zetten brandt hij je tong, en zo heet proef je vrijwel niets.', '600', 'nl'),
  ('1101-7-nl', '1101', 7, 'Slurp een lepel op en verstuif de koffie door je hele mond om het volume van de smaken omhoog te draaien. Blijf proeven terwijl hij afkoelt tot kamertemperatuur — hij verandert onderweg enorm en wordt steeds makkelijker te proeven.', '60', 'nl'),
  ('1101-1-no', '1101', 1, 'Kvern først en liten håndfull bønner for å rense kvernen. Kvern så <final_coffee_amount> g middels fint, mot det fine, og vei det rett ned i skålen eller koppen du skal brygge i.', '0', 'no'),
  ('1101-2-no', '1101', 2, 'Sett skålen på vekten og nullstill vekten. Hell <final_water_amount> g varmt vann over den malte kaffen — du trenger verken å helle forsiktig eller nøyaktig.', '15', 'no'),
  ('1101-3-no', '1101', 3, 'La kaffen trekke i 4 minutter. På overflaten danner det seg en skorpe av malt kaffe.', '240', 'no'),
  ('1101-4-no', '1101', 4, 'Rør forsiktig i skorpen tre ganger med en skje, og lukt på aromaen som slippes ut. Det meste av kaffen synker til bunnen.', '15', 'no'),
  ('1101-5-no', '1101', 5, 'Bruk en ny, ren skje til å skumme av skummet og alt som fortsatt flyter på overflaten.', '15', 'no'),
  ('1101-6-no', '1101', 6, 'La kaffen kjøle seg ned i minst 10 minutter. Rett etter brygging brenner den tungen, og så varm er den nesten umulig å smake på.', '600', 'no'),
  ('1101-7-no', '1101', 7, 'Slurp i deg en skje og spray kaffen ut i hele munnen for å skru opp volumet på smakene. Fortsett å smake mens den kjøler seg ned til romtemperatur — den endrer seg mye på veien og blir stadig lettere å smake.', '60', 'no'),
  ('1101-1-pl', '1101', 1, 'Najpierw zmiel małą garść ziaren, aby przepłukać młynek. Potem zmiel <final_coffee_amount> g na średnio drobno, bliżej drobnego, i odważ kawę bezpośrednio do miseczki lub kubka, w którym będziesz parzyć.', '0', 'pl'),
  ('1101-2-pl', '1101', 2, 'Postaw miseczkę na wadze i wyzeruj ją. Wlej <final_water_amount> g gorącej wody na zmieloną kawę — nie musisz lać delikatnie ani precyzyjnie.', '15', 'pl'),
  ('1101-3-pl', '1101', 3, 'Pozostaw kawę do naparzania na 4 minuty. Na powierzchni utworzy się kożuch ze zmielonej kawy.', '240', 'pl'),
  ('1101-4-pl', '1101', 4, 'Delikatnie zamieszaj kożuch trzy razy łyżką, wąchając uwalniający się aromat. Większość kawy opadnie na dno.', '15', 'pl'),
  ('1101-5-pl', '1101', 5, 'Drugą, czystą łyżką zbierz pianę i wszystko, co wciąż unosi się na powierzchni.', '15', 'pl'),
  ('1101-6-pl', '1101', 6, 'Odstaw kawę do ostygnięcia na co najmniej 10 minut. Zaraz po zaparzeniu poparzy ci język, a tak gorącej kawy prawie nie da się posmakować.', '600', 'pl'),
  ('1101-7-pl', '1101', 7, 'Siorbnij łyżkę, rozpylając kawę po całych ustach, aby podkręcić głośność smaków. Degustuj dalej, aż kawa osiągnie temperaturę pokojową — po drodze bardzo się zmienia i coraz łatwiej ją posmakować.', '60', 'pl'),
  ('1101-1-pt', '1101', 1, 'Primeiro moa um punhado pequeno de grãos para limpar o moedor. Depois moa <final_coffee_amount>g em uma moagem média-fina puxando para a fina e pese direto na tigela ou xícara em que vai preparar.', '0', 'pt'),
  ('1101-2-pt', '1101', 2, 'Coloque a tigela na balança e zere. Despeje <final_water_amount>g de água quente sobre o café moído — não precisa despejar com delicadeza nem com precisão.', '15', 'pt'),
  ('1101-3-pt', '1101', 3, 'Deixe o café em imersão por 4 minutos. Na superfície vai se formar uma crosta de café moído.', '240', 'pt'),
  ('1101-4-pt', '1101', 4, 'Mexa a crosta delicadamente três vezes com uma colher, sentindo o aroma que se libera. A maior parte do café moído vai afundar.', '15', 'pt'),
  ('1101-5-pt', '1101', 5, 'Com uma segunda colher limpa, retire a espuma e tudo o que ainda estiver boiando na superfície.', '15', 'pt'),
  ('1101-6-pt', '1101', 6, 'Deixe o café esfriar por pelo menos 10 minutos. Logo depois do preparo ele queima a língua, e tão quente é quase impossível sentir qualquer sabor.', '600', 'pt'),
  ('1101-7-pt', '1101', 7, 'Sorva uma colherada, espalhando o café por toda a boca para aumentar o volume dos sabores. Continue provando enquanto ele esfria até a temperatura ambiente — o café muda muito no caminho e fica cada vez mais fácil de provar.', '60', 'pt'),
  ('1101-1-ro', '1101', 1, 'Macină mai întâi o mână mică de boabe, ca să cureți râșnița. Apoi macină <final_coffee_amount>g la o granulație medie-fină, spre fin, și cântărește cafeaua direct în bolul sau cana în care vei prepara.', '0', 'ro'),
  ('1101-2-ro', '1101', 2, 'Așază bolul pe cântar și adu cântarul la zero. Toarnă <final_water_amount>g de apă fierbinte peste cafeaua măcinată — nu e nevoie să torni delicat sau precis.', '15', 'ro'),
  ('1101-3-ro', '1101', 3, 'Lasă cafeaua la infuzat 4 minute. La suprafață se va forma o crustă de cafea măcinată.', '240', 'ro'),
  ('1101-4-ro', '1101', 4, 'Amestecă ușor crusta de trei ori cu o lingură, mirosind aroma care se eliberează. Cea mai mare parte a cafelei măcinate va coborî la fund.', '15', 'ro'),
  ('1101-5-ro', '1101', 5, 'Cu o a doua lingură, curată, îndepărtează spuma și tot ce mai plutește la suprafață.', '15', 'ro'),
  ('1101-6-ro', '1101', 6, 'Lasă cafeaua să se răcească cel puțin 10 minute. Imediat după preparare îți arde limba, iar atât de fierbinte este aproape imposibil de gustat.', '600', 'ro'),
  ('1101-7-ro', '1101', 7, 'Soarbe zgomotos o lingură, pulverizând cafeaua în toată gura, ca să dai volumul mai tare pe arome. Continuă să guști pe măsură ce se răcește până la temperatura camerei — se schimbă mult pe drum și devine tot mai ușor de gustat.', '60', 'ro'),
  ('1101-1-ru', '1101', 1, 'Сначала смелите небольшую горсть зёрен, чтобы прочистить кофемолку. Затем смелите <final_coffee_amount> г в средне-мелкий помол, ближе к мелкому, и взвесьте кофе сразу в чаше или кружке, в которой будете заваривать.', '0', 'ru'),
  ('1101-2-ru', '1101', 2, 'Поставьте чашу на весы и обнулите их. Налейте <final_water_amount> г горячей воды на молотый кофе — лить аккуратно или точно не нужно.', '15', 'ru'),
  ('1101-3-ru', '1101', 3, 'Дайте кофе настояться 4 минуты. На поверхности образуется корка из молотого кофе.', '240', 'ru'),
  ('1101-4-ru', '1101', 4, 'Аккуратно перемешайте корку ложкой три раза, вдыхая аромат, который при этом высвобождается. Большая часть кофе осядет на дно.', '15', 'ru'),
  ('1101-5-ru', '1101', 5, 'Второй чистой ложкой снимите пену и всё, что ещё плавает на поверхности.', '15', 'ru'),
  ('1101-6-ru', '1101', 6, 'Дайте кофе остыть не меньше 10 минут. Сразу после заваривания он обожжёт язык, и таким горячим его почти невозможно распробовать.', '600', 'ru'),
  ('1101-7-ru', '1101', 7, 'Втяните ложку кофе с шумом, распыляя его по всему рту, — так вкусы звучат громче. Продолжайте пробовать, пока кофе остывает до комнатной температуры: по пути он сильно меняется и распробовать его становится всё легче.', '60', 'ru'),
  ('1101-1-tr', '1101', 1, 'Önce değirmeni temizlemek için küçük bir avuç çekirdek öğütün. Ardından <final_coffee_amount>g kahveyi inceye yakın orta-ince öğütün ve doğrudan demleyeceğiniz kâseye veya kupaya tartın.', '0', 'tr'),
  ('1101-2-tr', '1101', 2, 'Kâseyi terazinin üzerine koyun ve sıfırlayın. Öğütülmüş kahvenin üzerine <final_water_amount>g sıcak su dökün — nazikçe veya hassas dökmenize gerek yok.', '15', 'tr'),
  ('1101-3-tr', '1101', 3, 'Kahveyi 4 dakika demlenmeye bırakın. Yüzeyde öğütülmüş kahveden bir kabuk oluşacak.', '240', 'tr'),
  ('1101-4-tr', '1101', 4, 'Kabuğu bir kaşıkla üç kez nazikçe karıştırın ve açığa çıkan aromayı koklayın. Kahvenin çoğu dibe çökecek.', '15', 'tr'),
  ('1101-5-tr', '1101', 5, 'İkinci ve temiz bir kaşıkla köpüğü ve yüzeyde hâlâ yüzen parçacıkları alın.', '15', 'tr'),
  ('1101-6-tr', '1101', 6, 'Kahveyi en az 10 dakika soğumaya bırakın. Demlemenin hemen ardından dilinizi yakar ve o sıcaklıkta neredeyse hiçbir şeyin tadını alamazsınız.', '600', 'tr'),
  ('1101-7-tr', '1101', 7, 'Bir kaşık kahveyi höpürdeterek çekin ve ağzınızın tamamına yayın; böylece aromaların sesi yükselir. Oda sıcaklığına inene kadar tatmaya devam edin — kahve yol boyunca çok değişir ve tadını almak giderek kolaylaşır.', '60', 'tr'),
  ('1101-1-uk', '1101', 1, 'Спершу змеліть невелику жменю зерен, щоб прочистити кавомолку. Потім змеліть <final_coffee_amount> г у середньо-дрібний помел, ближче до дрібного, і зважте каву одразу в чаші або горнятку, у якому заварюватимете.', '0', 'uk'),
  ('1101-2-uk', '1101', 2, 'Поставте чашу на ваги й обнуліть їх. Налийте <final_water_amount> г гарячої води на мелену каву — лити обережно чи точно не потрібно.', '15', 'uk'),
  ('1101-3-uk', '1101', 3, 'Дайте каві настоятися 4 хвилини. На поверхні утвориться кірка з меленої кави.', '240', 'uk'),
  ('1101-4-uk', '1101', 4, 'Обережно перемішайте кірку ложкою тричі, вдихаючи аромат, що вивільняється. Більшість кави осяде на дно.', '15', 'uk'),
  ('1101-5-uk', '1101', 5, 'Другою, чистою ложкою зніміть піну та все, що ще плаває на поверхні.', '15', 'uk'),
  ('1101-6-uk', '1101', 6, 'Дайте каві охолонути щонайменше 10 хвилин. Одразу після заварювання вона обпече язик, і такою гарячою її майже неможливо розсмакувати.', '600', 'uk'),
  ('1101-7-uk', '1101', 7, 'Втягніть ложку кави з шумом, розпорошуючи її по всьому роті, — так смаки звучать гучніше. Продовжуйте куштувати, доки кава охолоне до кімнатної температури: дорогою вона дуже змінюється, і смакувати її стає дедалі легше.', '60', 'uk'),
  ('1101-1-zh', '1101', 1, '先磨一小把咖啡豆以清理磨豆机。然后将 <final_coffee_amount>g 咖啡磨成偏细的中细，直接称入要冲煮的碗或杯中。', '0', 'zh'),
  ('1101-2-zh', '1101', 2, '把碗放在秤上并归零。将 <final_water_amount>g 热水倒在咖啡粉上——注水不需要轻柔或精准。', '15', 'zh'),
  ('1101-3-zh', '1101', 3, '让咖啡浸泡 4 分钟。表面会形成一层咖啡粉壳。', '240', 'zh'),
  ('1101-4-zh', '1101', 4, '用汤匙轻轻搅拌粉壳三次，同时闻散发出来的香气。大部分咖啡粉会沉到底部。', '15', 'zh'),
  ('1101-5-zh', '1101', 5, '换一把干净的汤匙，撇去泡沫和仍浮在表面的咖啡粉。', '15', 'zh'),
  ('1101-6-zh', '1101', 6, '让咖啡冷却至少 10 分钟。刚冲好时会烫伤舌头，那么烫几乎尝不出任何风味。', '600', 'zh'),
  ('1101-7-zh', '1101', 7, '啜吸一匙，让咖啡雾化喷洒到整个口腔，把风味的音量调大。在它冷却到室温的过程中持续品尝——一路上风味变化很大，也会越来越容易尝出来。', '60', 'zh')
