-- Bundled cupping recipe 1101: James Hoffmann's at-home cupping.
-- Source: https://www.youtube.com/watch?v=cSEgP4VNynQ
--
-- First recipe for the existing 'cupping' brewing method. Per-bowl amounts
-- (12 g / 200 g = Hoffmann's 60 g/L), so the app's scaler covers larger mugs.
-- Step times are per-step seconds and sum to recipes.brew_time (945).
-- Translations follow docs/translation-rules.md.

begin;

on conflict (id) do update set
  brewing_method_id = excluded.brewing_method_id,
  coffee_amount     = excluded.coffee_amount,
  water_amount      = excluded.water_amount,
  water_temp        = excluded.water_temp,
  vendor_id         = excluded.vendor_id,
  last_modified     = excluded.last_modified,
  brew_time         = excluded.brew_time;

on conflict (id) do update set
  name              = excluded.name,
  grind_size        = excluded.grind_size,
  short_description = excluded.short_description;

on conflict (id) do update set
  step_order  = excluded.step_order,
  description = excluded.description,
  "time"      = excluded."time";

commit;
